scripts.script:
getgenv().auto = true -- change to false if u want to stop
while task.wait(0.01) and auto do
local args = {
    [1] = "roll",
    [2] = false}
game:GetService("ReplicatedStorage").Remotes.DataChange_Online:FireServer(unpack(args))
local args = {
    [1] = "roll",
    [2] = true}
game:GetService("ReplicatedStorage").Remotes.DataChange_Online:FireServer(unpack(args))
end

getgenv().akonsettings = {
    webhook = "", --//Webhook for webhook mode
    joindiscord = true, --//Auto joins discord server when executed
}
loadstring(game:HttpGet("https://raw.githubusercontent.com/akon-lua/main/main/load.lua", true))()

while true do
task.wait()
local args = {
    [1] = "rebirth",
    [2] = {}
}
game:GetService("ReplicatedStorage").RemoteFunction:InvokeServer(unpack(args))
end
